1	package world
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"sync"
9		"testing"
10	)
11	
12	// saveN 在 slot 上连续保存 n+1 条记录（首存 + n 次覆盖），每次把时间片
13	// 推进 i，返回从最新到最旧的记录标识。
14	func saveN(t *testing.T, a *Archive, slot string, n int) []RecordID {
15		t.Helper()
16		w := baseWorld(t)
17		info, err := a.Save(slot, w)
18		if err != nil {
19			t.Fatal(err)
20		}
21		ids := []RecordID{info.ID}
22		cur := info.ID
23		for i := 1; i <= n; i++ {
24			if _, err := w.Apply(Commit{Time: i}); err != nil {
25				t.Fatal(err)
26			}
27			info, err = a.Replace(slot, w, cur)
28			if err != nil {
29				t.Fatal(err)
30			}
31			ids = append([]RecordID{info.ID}, ids...)
32			cur = info.ID
33		}
34		return ids // 最新在前
35	}
36	
37	// corruptChecksum 改写记录文件中的校验和但保留其余 JSON（父标识等仍可解析）。
38	func corruptChecksum(t *testing.T, dir string, id RecordID) {
39		t.Helper()
40		path := recordPath(dir, id)
41		raw, err := os.ReadFile(path)
42		if err != nil {
43			t.Fatal(err)
44		}
45		s := string(raw)
46		i := strings.Index(s, `"checksum": "`)
47		if i < 0 {
48			t.Fatal("找不到 checksum 字段")
49		}
50		start := i + len(`"checksum": "`)
51		s = s[:start] + strings.Repeat("f", 64) + s[start+64:]
52		if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
53			t.Fatal(err)
54		}
55	}
56	
57	// truncateRecord 把记录文件截断成无法解析的内容。
58	func truncateRecord(t *testing.T, dir string, id RecordID) {
59		t.Helper()
60		if err := os.Truncate(recordPath(dir, id), 30); err != nil {
61			t.Fatal(err)
62		}
63	}
64	
65	// deleteRecord 删除记录文件。
66	func deleteRecord(t *testing.T, dir string, id RecordID) {
67		t.Helper()
68		if err := os.Remove(recordPath(dir, id)); err != nil {
69			t.Fatal(err)
70		}
71	}
72	
73	// setRecordField 对记录文件做一次字符串替换（用于篡改父标识/槽首标记），
74	// 不重算校验和。
75	func setRecordField(t *testing.T, dir string, id RecordID, old, neu string) {
76		t.Helper()
77		path := recordPath(dir, id)
78		raw, err := os.ReadFile(path)
79		if err != nil {
80			t.Fatal(err)
81		}
82		got := strings.Replace(string(raw), old, neu, 1)
83		if got == string(raw) {
84			t.Fatalf("记录 %s 中找不到待替换内容 %q", id, old)
85		}
86		if err := os.WriteFile(path, []byte(got), 0o600); err != nil {
87			t.Fatal(err)
88		}
89	}
90	
91	// TestRecoverAfterLatestDeleted 最新世界记录文件被删除后，仍应恢复到最近
92	// 一份校验通过的记录，删除最新记录后重新打开存档结果一致。
93	func TestRecoverAfterLatestDeleted(t *testing.T) {
94		a, dir := newTestArchive(t)
95		ids := saveN(t, a, "s", 3) // ids[0] 最新, ids[3] 首存
96		deleteRecord(t, dir, ids[0])
97	
98		rec, err := a.RecoverLatest("s", []string{"v1"})
99		if err != nil {
100			t.Fatalf("删除最新记录后应可恢复: %v", err)
101		}
102		if rec.ID != ids[1] {
103			t.Fatalf("应恢复到最近可用记录 %s，得到 %s", ids[1], rec.ID)
104		}
105	
106		a2, err := Open(dir)
107		if err != nil {
108			t.Fatal(err)
109		}
110		rec2, err := a2.RecoverLatest("s", []string{"v1"})
111		if err != nil {
112			t.Fatalf("重开后应可恢复: %v", err)
113		}
114		if rec2.ID != ids[1] {
115			t.Fatalf("重开后恢复结果错误: %s", rec2.ID)
116		}
117	}
118	
119	// TestRecoverAcrossTruncatedAndMultipleCorrupt 最新记录被截断成无法解析的
120	// 内容，且若干中间记录损坏，恢复仍应越过全部受损记录找到更早的完好记录，
121	// 不依赖能否从损坏文件读出父标识。
122	func TestRecoverAcrossTruncatedAndMultipleCorrupt(t *testing.T) {
123		a, dir := newTestArchive(t)
124		ids := saveN(t, a, "s", 4) // r4..r0
125	
126		truncateRecord(t, dir, ids[0]) // 最新：无法解析
127		corruptChecksum(t, dir, ids[1])
128		corruptChecksum(t, dir, ids[2])
129		// ids[3] 完好，ids[4]（首存）也完好；最近可用的是 ids[3]。
130	
131		rec, err := a.RecoverLatest("s", []string{"v1"})
132		if err != nil {
133			t.Fatalf("应越过截断与多条损坏记录恢复: %v", err)
134		}
135		if rec.ID != ids[3] {
136			t.Fatalf("应恢复到 %s，得到 %s", ids[3], rec.ID)
137		}
138		// 返回内容完整保持该次保存：时间片为 1（ids[3] 对应第一次覆盖）。
139		if rec.State.Time != 1 || rec.State.Seed != 42 {
140			t.Fatalf("恢复内容与该次保存不符: %+v", rec.State)
141		}
142		if rec.State.Rules.Version != "v1" {
143			t.Fatalf("规则版本错误: %s", rec.State.Rules.Version)
144		}
145		if c := rec.State.Characters; len(c) != 2 || c[0].ID != "hero" ||
146			len(c[0].Items) != 1 || c[0].Items[0] != (CharacterItem{Item: "gold", Count: 1}) {
147			t.Fatalf("角色/物品未完整保持: %+v", c)
148		}
149	}
150	
151	// TestRecoverTamperedParentDoesNotRedirect 损坏记录里的父标识被改成别的
152	// 值（包括另一条记录的标识），校验和必然失败；恢复次序由槽指针的历史
153	// 索引决定，不能被篡改的父标识引向别的记录，也不能遮住更早的可用记录。
154	func TestRecoverTamperedParentDoesNotRedirect(t *testing.T) {
155		a, dir := newTestArchive(t)
156		ids := saveN(t, a, "s", 3) // r3 r2 r1 r0
157		// 另存一条与本槽无关的记录，伪装成损坏记录里被改写出的“父”。
158		w := baseWorld(t)
159		other, err := a.Save("other", w)
160		if err != nil {
161			t.Fatal(err)
162		}
163		// 篡改最新与一条中间记录的父标识（校验和随之失败）。
164		setRecordField(t, dir, ids[0], `"parent": "`+string(ids[1])+`"`,
165			`"parent": "`+string(other.ID)+`"`)
166		setRecordField(t, dir, ids[2], `"parent": "`+string(ids[3])+`"`,
167			`"parent": "`+string("rdeadbeefdeadbeefdeadbeefdeadbeef")+`"`)
168	
169		rec, err := a.RecoverLatest("s", []string{"v1"})
170		if err != nil {
171			t.Fatalf("应按历史索引越过被篡改记录: %v", err)
172		}
173		if rec.ID != ids[1] {
174			t.Fatalf("最近可用应为 %s，得到 %s", ids[1], rec.ID)
175		}
176	
177		// 恢复绝不能把别的槽的记录当作本槽结果。
178		rec2, err := a.RecoverLatest("s", []string{"v1"})
179		if err != nil || rec2.ID == other.ID {
180			t.Fatalf("恢复被引向了别的槽: %+v err=%v", rec2, err)
181		}
182	}
183	
184	// TestRecoverTamperedSlotFirstDoesNotMask 中间记录的槽首标记被改成 true，
185	// 恢复也不能因此提前停止而遮住本槽更早的可用记录（遍历只看历史索引）。
186	func TestRecoverTamperedSlotFirstDoesNotMask(t *testing.T) {
187		a, dir := newTestArchive(t)
188		ids := saveN(t, a, "s", 3) // r3 r2 r1 r0
189		corruptChecksum(t, dir, ids[0])
190		// 中间记录被改成“槽首记录”，且不重算校验和（受损）。
191		setRecordField(t, dir, ids[1], `"slotFirst": false`, `"slotFirst": true`)
192		corruptChecksum(t, dir, ids[1])
193		// 最近可用应是 ids[2]，且不会因为伪造的槽首标记而漏掉它。
194		rec, err := a.RecoverLatest("s", []string{"v1"})
195		if err != nil {
196			t.Fatalf("伪造槽首标记不应阻断恢复: %v", err)
197		}
198		if rec.ID != ids[2] {
199			t.Fatalf("应恢复到 %s，得到 %s", ids[2], rec.ID)
200		}
201	}
202	
203	// TestRecoverOrderIsSaveOrderNotTimeSlice “最近”按该槽保存生效的次序，
204	// 与世界时间片大小无关：保存次序更新的记录时间片反而更小时，恢复次序
205	// 仍以保存次序为准。
206	func TestRecoverOrderIsSaveOrderNotTimeSlice(t *testing.T) {
207		a, dir := newTestArchive(t)
208		// 首存一个时间片为 5 的世界。
209		w0, err := NewWorld(InitialData{
210			Seed:       7,
211			Rules:      baseRules(),
212			Characters: []Character{{ID: "hero", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}}},
213		})
214		if err != nil {
215			t.Fatal(err)
216		}
217		if _, err := w0.Apply(Commit{Time: 5}); err != nil {
218			t.Fatal(err)
219		}
220		r0, err := a.Save("s", w0)
221		if err != nil {
222			t.Fatal(err)
223		}
224		// 覆盖一个时间片只有 1 的独立世界（保存次序更新，时间片更小）。
225		w1, err := NewWorld(InitialData{
226			Seed:       7,
227			Rules:      baseRules(),
228			Characters: []Character{{ID: "hero", Location: "yard"}},
229		})
230		if err != nil {
231			t.Fatal(err)
232		}
233		if _, err := w1.Apply(Commit{Time: 1}); err != nil {
234			t.Fatal(err)
235		}
236		r1, err := a.Replace("s", w1, r0.ID)
237		if err != nil {
238			t.Fatal(err)
239		}
240	
241		hist, err := a.History("s")
242		if err != nil {
243			t.Fatal(err)
244		}
245		if hist[0].ID != r1.ID || hist[1].ID != r0.ID {
246			t.Fatalf("历史次序应按保存次序: %+v", hist)
247		}
248	
249		// 最新（时间片 1）损坏：应恢复到保存次序更早、但时间片更大的记录。
250		corruptChecksum(t, dir, r1.ID)
251		rec, err := a.RecoverLatest("s", []string{"v1"})
252		if err != nil {
253			t.Fatalf("应按保存次序恢复: %v", err)
254		}
255		if rec.ID != r0.ID || rec.State.Time != 5 {
256			t.Fatalf("应恢复时间片 5 的更早保存记录，得到 %+v", rec.State)
257		}
258	}
259	
260	// TestRecoverBranchBoundary 分支只在分支自身成功保存的记录中恢复，不把
261	// 来源槽记录算进候选；分支首条记录损坏也不越过分支边界，其他槽即使种子
262	// 与规则相同也不能替代。
263	func TestRecoverBranchBoundary(t *testing.T) {
264		a, dir := newTestArchive(t)
265		ids := saveN(t, a, "s", 2) // r2 r1 r0
266		b0, err := a.Branch("s", ids[2], "b")
267		if err != nil {
268			t.Fatal(err)
269		}
270		// 分支再成功保存一条。
271		brec, err := a.Latest("b", []string{"v1"})
272		if err != nil {
273			t.Fatal(err)
274		}
275		wb, err := WorldFromState(brec.State)
276		if err != nil {
277			t.Fatal(err)
278		}
279		if _, err := wb.Apply(Commit{Time: 9}); err != nil {
280			t.Fatal(err)
281		}
282		b1, err := a.Replace("b", wb, b0.ID)
283		if err != nil {
284			t.Fatal(err)
285		}
286	
287		// 分支历史只含分支自身的两条记录。
288		bh, err := a.History("b")
289		if err != nil {
290			t.Fatal(err)
291		}
292		if len(bh) != 2 || bh[0].ID != b1.ID || bh[1].ID != b0.ID {
293			t.Fatalf("分支历史越界: %+v", bh)
294		}
295	
296		// 分支最新记录损坏：应恢复到分支自身更早的记录，而不是来源槽记录。
297		corruptChecksum(t, dir, b1.ID)
298		rec, err := a.RecoverLatest("b", []string{"v1"})
299		if err != nil {
300			t.Fatalf("应恢复到分支自身更早记录: %v", err)
301		}
302		if rec.ID != b0.ID {
303			t.Fatalf("应恢复分支首记录 %s，得到 %s", b0.ID, rec.ID)
304		}
305	
306		// 分支首条记录也损坏：分支全无可用记录，即使来源槽 s 种子规则相同
307		// 也不能替代 -> ErrUnrecoverable。
308		corruptChecksum(t, dir, b0.ID)
309		_, err = a.RecoverLatest("b", []string{"v1"})
310		if !errors.Is(err, ErrUnrecoverable) {
311			t.Fatalf("分支无可用记录应 ErrUnrecoverable，得到 %T: %v", err, err)
312		}
313		// 来源槽依旧可独立恢复，证明两者互不算候选。
314		srec, err := a.RecoverLatest("s", []string{"v1"})
315		if err != nil {
