475	// TestRecoverCASLoserNotCandidate 并发覆盖同一父记录时竞争失败的写入不
476	// 得进入恢复候选：恰好一个成功，失败者连记录文件都不会留下；胜出记录
477	// 损坏后，恢复只能落到被覆盖的父记录。
478	func TestRecoverCASLoserNotCandidate(t *testing.T) {
479		a, dir := newTestArchive(t)
480		w := baseWorld(t)
481		r0, err := a.Save("s", w)
482		if err != nil {
483			t.Fatal(err)
484		}
485		if _, err := w.Apply(Commit{Time: 1}); err != nil {
486			t.Fatal(err)
487		}
488	
489		const n = 6
490		var wg sync.WaitGroup
491		var mu sync.Mutex
492		wins, conflicts := 0, 0
493		for i := 0; i < n; i++ {
494			wg.Add(1)
495			go func() {
496				defer wg.Done()
497				ga, err := Open(dir)
498				if err != nil {
499					t.Error(err)
500					return
501				}
502				_, err = ga.Replace("s", w, r0.ID)
503				mu.Lock()
504				defer mu.Unlock()
505				switch {
506				case err == nil:
507					wins++
508				case isConflict(err):
509					conflicts++
510				default:
511					t.Errorf("非冲突错误: %v", err)
512				}
513			}()
514		}
515		wg.Wait()
516		if wins != 1 || conflicts != n-1 {
517			t.Fatalf("期望 1 成功 %d 冲突，得到 %d 成功 %d 冲突", n-1, wins, conflicts)
518		}
519	
520		latest, err := a.Latest("s", []string{"v1"})
521		if err != nil {
522			t.Fatal(err)
523		}
524		if latest.Parent != r0.ID {
525			t.Fatalf("胜出记录父应为 %s，得到 %s", r0.ID, latest.Parent)
526		}
527		// 历史只含胜出记录与父记录，竞争失败的写入不在其中。
528		hist, err := a.History("s")
529		if err != nil || len(hist) != 2 {
530			t.Fatalf("历史应只有胜出记录与父记录: %+v err=%v", hist, err)
531		}
532	
533		// 胜出记录损坏：恢复只能落到父记录，绝不会选中任何竞争失败的写入。
534		corruptChecksum(t, dir, latest.ID)
535		rec, err := a.RecoverLatest("s", []string{"v1"})
536		if err != nil {
537			t.Fatalf("应恢复到被覆盖的父记录: %v", err)
538		}
539		if rec.ID != r0.ID {
540			t.Fatalf("应恢复父记录 %s，得到 %s", r0.ID, rec.ID)
541		}
542	}
