228		updatePointer(t, a, "s", r2)
229	
230		// Latest 在仅接受 v1 时拒绝最新记录；恢复读取应越过 v2 找到 r1。
231		if _, err := a.Latest("s", []string{"v1"}); err == nil {
232			t.Fatal("v2 最新记录应被版本拒绝")
233		}
234		rec, err := a.RecoverLatest("s", []string{"v1"})
235		if err != nil {
236			t.Fatalf("应恢复到 v1 历史记录: %v", err)
237		}
238		if rec.ID != r1.ID {
239			t.Fatalf("应恢复到最近可接受记录 %s，得到 %s", r1.ID, rec.ID)
240		}
241		// 恢复读取不改写槽指针与历史。
242		ptr, err := a.readLatestLocked("s")
243		if err != nil {
244			t.Fatal(err)
245		}
246		if ptr != r2 {
247			t.Fatal("恢复读取改写了槽指针")
248		}
249	
250		// 损坏最新记录：改写其校验和（JSON 仍可解析，父指针仍在）。
251		// Latest 报损坏；恢复应越过它，沿父指针找到可接受记录。
252		{
253			path := recordPath(dir, r2)
254			raw, err := os.ReadFile(path)
255			if err != nil {
256				t.Fatal(err)
257			}
258			s := string(raw)
259			i := strings.Index(s, `"checksum": "`)
260			if i < 0 {
261				t.Fatal("找不到 checksum 字段")
262			}
263			start := i + len(`"checksum": "`)
264			end := start + 64
265			s = s[:start] + strings.Repeat("0", 64) + s[end:]
266			if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
267				t.Fatal(err)
268			}
269		}
270		if _, err := a.Latest("s", []string{"v1", "v2"}); err == nil {
271			t.Fatal("损坏记录应报错")
272		} else {
273			var ce *CorruptError
274			if !errors.As(err, &ce) {
275				t.Fatalf("应返回 CorruptError，得到 %T", err)
276			}
277		}
278		rec2, err := a.RecoverLatest("s", []string{"v1"})
279		if err != nil {
280			t.Fatalf("应越过损坏记录恢复: %v", err)
281		}
282		if rec2.ID != r1.ID {
283			t.Fatalf("恢复结果错误: %s", rec2.ID)
284		}
285	
286		// 连最后可接受的根也不可接受时 -> 不可恢复。
287		_, err = a.RecoverLatest("s", []string{"v9"})
288		if !errors.Is(err, ErrUnrecoverable) {
289			t.Fatalf("应返回 ErrUnrecoverable，得到 %T: %v", err, err)
290		}
291	
292		// r0 仍完好且可按标识读取（在进一步截断链之前）。
293		r0rec, err := a.Record("s", r0.ID, []string{"v1"})
294		if err != nil {
295			t.Fatal(err)
296		}
297		if r0rec.ID != r0.ID {
298			t.Fatal("根记录读取错误")
299		}
300	
301		// 最新记录被截断到无法解析时，历史索引仍保留保存次序，恢复应越过
302		// 它找到更早的可用记录（不能因为读不出父标识就放弃）。
303		if err := os.Truncate(recordPath(dir, r2), 40); err != nil {
304			t.Fatal(err)
305		}
306		rec3, err := a.RecoverLatest("s", []string{"v1"})
307		if err != nil {
308			t.Fatalf("最新记录被截断成无法解析的内容时仍应恢复到更早记录: %v", err)
309		}
310		if rec3.ID != r1.ID {
311			t.Fatalf("应越过被截断的最新记录恢复到 %s，得到 %s", r1.ID, rec3.ID)
312		}
313		// 重新打开存档后结果一致。
314		a3, err := Open(dir)
315		if err != nil {
316			t.Fatal(err)
317		}
318		rec4, err := a3.RecoverLatest("s", []string{"v1"})
319		if err != nil {
320			t.Fatalf("重开后恢复结果不一致: %v", err)
321		}
322		if rec4.ID != r1.ID {
323			t.Fatalf("重开后应恢复到 %s，得到 %s", r1.ID, rec4.ID)
324		}
325	}
