415	func TestReloadWorldPreservesTime(t *testing.T) {
416		a, _ := newTestArchive(t)
417		w := baseWorld(t)
418		r0, _ := a.Save("s", w)
419		_, _ = w.Apply(Commit{
420			Moves:       []Move{{Character: "hero", To: "yard"}},
421			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 1}},
422			Time:        7,
423		})
424		r1, _ := a.Replace("s", w, r0.ID)
425	
426		rec, err := a.Latest("s", []string{"v1"})
427		if err != nil {
428			t.Fatal(err)
429		}
430		// 读档续玩：时间片与其它状态一起恢复，而不是重置为 0。
431		loaded, err := WorldFromState(rec.State)
432		if err != nil {
433			t.Fatal(err)
434		}
435		got := loaded.Snapshot()
