455	// writeRawRecord 直接写入一条记录文件并返回其标识，供损坏/版本测试使用。
456	func writeRawRecord(t *testing.T, a *Archive, parent RecordID, first bool, st State) RecordID {
457		t.Helper()
458		id, err := newRecordID()
459		if err != nil {
460			t.Fatal(err)
461		}
462		env := &envelope{
463			Format:    archiveFormatVersion,
464			ID:        id,
465			Parent:    parent,
466			SlotFirst: first,
467			State:     st,
468		}
469		env.Checksum = computeChecksum(env)
470		if err := writeRecord(a.dir, env); err != nil {
471			t.Fatal(err)
472		}
473		return id
474	}
