476	// updatePointer 模拟一个遵循磁盘格式的写入器：新记录已完整落盘后原子
477	// 更新槽指针，并把新记录按保存次序前置到历史索引。
478	func updatePointer(t *testing.T, a *Archive, slot string, id RecordID) {
479		t.Helper()
480		lock, err := acquireLock(a.dir)
481		if err != nil {
482			t.Fatal(err)
483		}
484		defer lock.release()
485		old, err := a.readSlotPointerLocked(slot)
486		if err != nil {
487			t.Fatal(err)
488		}
489		history := []RecordID{id}
490		for _, hid := range old.History {
491			if hid != id {
492				history = append(history, hid)
493			}
494		}
495		if err := a.persistSlotPointerLocked(slot, slotPointer{Latest: id, History: history}); err != nil {
496			t.Fatal(err)
497		}
498	}
