	return RecordInfo{}, err
}
// 记录完整落盘后才原子更新指针：新记录前置进保存次序，旧历史原样
// 保留。崩溃在这一步之前，槽保持确认前的指向与历史，新记录因不在
// 历史索引中而不会进入恢复候选。
if err := a.commitSlotPointerLocked(slot, oldPointer, oldPointer.Latest, id); err != nil {
	return RecordInfo{}, err
}
